int containerMostWater_10(const vector<int>& h) { int lo = 0, hi = (int)h.size() - 1, best = 0; while (lo < hi) { int w = hi - lo; if (h[lo] < h[hi]) { int cur = h[lo] * w; if (cur > best) best = cur; ++lo; } else { int cur = h[hi] * w; if (cur > best) best = cur; --hi; } } return best; }
int trappingRainWater_10(const vector<int>& h) { int lo = 0, hi = (int)h.size() - 1, lmax = 0, rmax = 0, ans = 0; while (lo <= hi) { if (h[lo] <= h[hi]) { if (h[lo] >= lmax) lmax = h[lo]; else ans += lmax - h[lo]; ++lo; } else { if (h[hi] >= rmax) rmax = h[hi]; else ans += rmax - h[hi]; --hi; } } return ans; }
vector<int> sortedSquaresMerge_10(const vector<int>& a) { int n = a.size(); vector<int> res(n); int lo = 0, hi = n - 1, p = n - 1; while (lo <= hi) { int s1 = a[lo] * a[lo], s2 = a[hi] * a[hi]; if (s1 > s2) { res[p--] = s1; ++lo; } else { res[p--] = s2; --hi; } } return res; }
int removeTargetVal_10(vector<int>& a, int val) { int k = 0; for (int i = 0; i < (int)a.size(); ++i) if (a[i] != val) a[k++] = a[i]; return k; }
int removeDuplicatesSorted_10(vector<int>& a) { if (a.empty()) return 0; int slow = 0; for (int fast = 1; fast < (int)a.size(); ++fast) if (a[fast] != a[slow]) a[++slow] = a[fast]; return slow + 1; }
vector<double> slidingWindowAverage_10(const vector<int>& a, int k) { int n = a.size(); vector<double> res; if (n < k || k <= 0) return res; double s = 0; for (int i = 0; i < k; ++i) s += a[i]; res.push_back(s / k); for (int i = k; i < n; ++i) { s += a[i] - a[i - k]; res.push_back(s / k); } return res; }
